INSERT INTO `homecats` VALUES (1,'橘子-1','橘子-1','猫猫有话说：幸福的猫生就是吃不完的毛条和猫猫罐头。','/uploads/home-cats/orange-1.png',10,1,1,1,NULL,NULL),(2,'橘子-2','橘子-2','猫猫有话说：为什么猫抓盆，变得越来越小了，只能蜷在里面睡觉了。','/uploads/home-cats/orange-2.png',20,1,0,1,NULL,NULL),(3,'橘子-3','橘子-3','猫猫有话说：家里来了只新猫，叫辛巴。','/uploads/home-cats/orange-3.png',30,1,0,1,NULL,NULL),(4,'橘子-4','橘子-4','猫猫有话说：不想呆在家里，想去外面的草地奔跑。','/uploads/home-cats/orange-4.png',40,1,0,1,NULL,NULL),(5,'橘子-5','橘子-5','猫猫有话说：主人为什么总是晚上才回家，还会忘记给我放粮。','/uploads/home-cats/orange-5.png',50,1,0,1,NULL,NULL),(6,'橘子-6','橘子-6','猫猫有话说：今天的厕所，又是脏的，坏主人不铲屎。','/uploads/home-cats/orange-6.png',60,1,0,1,NULL,NULL),(7,'625-1','625-1','猫猫有话说：早上起来要给我拍拍屁股。','/uploads/home-cats/625-1.png',70,1,0,1,NULL,NULL),(8,'625-2','625-2','猫猫有话说：今晚的主场是我，记得先摸摸我再去看文章。','/uploads/home-cats/625-2.png',80,1,0,1,NULL,NULL),(9,'微信图片_20260414151432_59_9','辛巴','我叫辛巴，一个冷酷的jio拇指杀手。','/uploads/home-cats/20260414151957-yptmr2-img_20260414_151903.png',90,1,0,1,'2026-04-14 15:15:41','2026-04-14 15:20:00');
